package com.example.swarmhunter
import com.example.swarmhunter.game.*
import org.junit.Assert.*
import org.junit.Test
class RoomInteractionTest {
 private fun plane(id:String,z:Float,kind:RoomSurfaceKind=RoomSurfaceKind.WALL)=RoomSurface(id,kind,V3(0f,0f,z),Q4(0f,0f,0f,1f),listOf(V3(-2f,-2f,0f),V3(2f,-2f,0f),V3(2f,2f,0f),V3(-2f,2f,0f)),listOf(0,1,2,0,2,3))
 private val origin=V3(0f,0f,0f);private val forward=V3(0f,0f,-1f)
 @Test fun energyRicochetsOnlyFromWalls(){assertTrue(canRicochet(2,RoomSurfaceKind.WALL));assertFalse(canRicochet(2,RoomSurfaceKind.TABLE));assertFalse(canRicochet(2,RoomSurfaceKind.FLOOR));assertFalse(canRicochet(0,RoomSurfaceKind.WALL))}
 @Test fun shortBeamNeverPassesItsImpactPoint(){assertEquals(0f,beamLengthScale(.10f),.0001f);assertEquals(0f,beamLengthScale(.17f),.0001f)}
 @Test fun latestSnapshotWinsAndTrackingLossRejectsPendingLoads(){val g=RoomSnapshotGate();val first=g.request();val last=g.request();assertFalse(g.accepts(first));assertTrue(g.accepts(last));g.invalidate();assertFalse(g.accepts(last))}
 @Test fun temporaryTrackingLossPreservesAnchorStateUntilGraceExpires(){val g=RoomTrackingGrace();g.update(true,.01f);g.update(false,.4f);assertFalse(g.available);assertFalse(g.expired);g.update(true,.01f);assertTrue(g.available);assertFalse(g.expired);g.update(false,2.1f);assertTrue(g.expired)}
 @Test fun simultaneousHandsCannotConsumeBothSlotsAtOnePosition(){val r=RoomSurfaceRegistry();val a=plane("a",-1f);r.replace(listOf(a));val h=r.cast(origin,forward,3f)!!;val t=TrapController();t.pinch(0,false,h,r);t.pinch(1,false,h,r);assertNotNull(t.pinch(0,true,h,r));assertNull(t.pinch(1,true,h,r));assertEquals(1,t.traps.size)}
 @Test fun wallImmediatelyBeforeTargetStillBlocksPulse(){val r=RoomSurfaceRegistry();val mount=plane("mount",0f,RoomSurfaceKind.TABLE);r.replace(listOf(mount,plane("wall",-.69f)));val t=TrapController();val h=SurfaceHit(mount,1f,origin,V3(0f,0f,1f));t.pinch(0,false,h,r);t.pinch(0,true,h,r);assertTrue(t.tick(1.1f,r,listOf(1 to V3(0f,0f,-.7f))).isEmpty());assertEquals(1,t.traps.size)}
 @Test fun reshapedPlaneCannotLeaveTrapOutsideItsBoundary(){val r=RoomSurfaceRegistry();val a=plane("a",-1f);r.replace(listOf(a));val t=TrapController();val hit=r.cast(V3(1.5f,0f,0f),forward,3f)!!;t.pinch(0,false,hit,r);t.pinch(0,true,hit,r);assertEquals(1,t.traps.size);r.replace(listOf(a.copy(vertices=a.vertices.map{it*.25f})));t.reconcile(r);assertTrue(t.traps.isEmpty())}
 @Test fun restoredHandResumesOnlyWithValidSavedPose(){val g=GestureMemory();val pose=List(15){.4f};repeat(26){g.register(pose,pose,.1f)};assertTrue(g.fire(0,pose,.02f));assertTrue(g.isMatching(0));assertFalse(g.fire(0,null,.25f));assertFalse(g.isMatching(0));assertFalse(g.fire(0,List(15){1.4f},.02f));assertTrue(g.fire(0,pose,.02f));assertTrue(g.registered)}
 @Test fun wallStopsEnemyBehindItAndNearestSurfaceWins(){val r=RoomSurfaceRegistry();r.replace(listOf(plane("far",-3f),plane("near",-1f)));val h=r.cast(origin,forward,5f);assertNotNull(h);assertEquals("near",h!!.surface.id);assertNull(nearestCombatHit(listOf(9 to 2f),h,5f)!!.enemy);assertEquals(8,nearestCombatHit(listOf(8 to .5f,9 to 2f),h,5f)!!.enemy)}
 @Test fun planeRemovalAndMovedAnchorsReplaceOldGeometry(){val r=RoomSurfaceRegistry();r.replace(listOf(plane("a",-1f)));r.replace(listOf(plane("a",-2f)));assertEquals(2f,r.cast(origin,forward,5f)!!.distance,.001f);r.replace(emptyList());assertNull(r.cast(origin,forward,5f))}
 @Test fun ricochetIsBoundedAndRetainsLifetime(){val b=RicochetState(forward);b.advance(.8f,5.6f);assertTrue(b.reflect(V3(0f,0f,1f)));assertEquals(5.6f,b.speed,.001f);assertEquals(1f,b.direction.z,.001f);assertTrue(b.reflect(V3(0f,0f,-1f)));assertFalse(b.reflect(V3(0f,0f,1f)));b.advance(.61f,1f);assertTrue(b.expired)}
 @Test fun releaseGateLimitsPlacementsAndLostTrackingDoesNotPlace(){val r=RoomSurfaceRegistry();r.replace(listOf(plane("a",-1f)));val hit=r.cast(origin,forward,3f)!!;val t=TrapController();assertNull(t.pinch(0,true,hit,r));assertNull(t.pinch(0,false,hit,r));assertNotNull(t.pinch(0,true,hit,r));assertNull(t.pinch(0,true,hit,r));val other=r.cast(V3(.4f,0f,0f),forward,3f)!!;t.pinch(1,false,other,r);assertNotNull(t.pinch(1,true,other,r));t.pinch(0,false,hit,r);assertNull(t.pinch(0,true,hit,r));t.undo();t.pinch(0,null,hit,r);assertNull(t.pinch(0,true,hit,r));assertEquals(1,t.traps.size);r.replace(emptyList());t.reconcile(r);assertTrue(t.traps.isEmpty())}
 @Test fun markerRequiresFootprintInsideActualPlane(){val r=RoomSurfaceRegistry();r.replace(listOf(plane("a",-1f)));assertTrue(r.canPlace(r.cast(origin,forward,3f)!!));assertFalse(r.canPlace(r.cast(V3(1.99f,0f,0f),forward,3f)!!))}
 @Test fun wallBlocksTriggerButTableDoesNotAndTrapIsSingleUse(){val r=RoomSurfaceRegistry();val surface=plane("mount",0f,RoomSurfaceKind.TABLE);r.replace(listOf(surface,plane("block",-.4f)));val mount=SurfaceHit(surface,1f,origin,V3(0f,0f,1f));val t=TrapController();t.pinch(0,false,mount,r);assertNotNull(t.pinch(0,true,mount,r));assertTrue(t.tick(1.1f,r,listOf(1 to V3(0f,0f,-.7f))).isEmpty());assertEquals(1,t.traps.size);r.replace(listOf(surface));val hits=t.tick(.01f,r,listOf(1 to V3(0f,0f,-.7f)));assertEquals(listOf(1),hits.single().second);assertTrue(t.tick(.1f,r,listOf(1 to V3(0f,0f,-.7f))).isEmpty())}
}
